#include <stdio.h>
#include <stdlib.h>

struct Node {
    int val;
    struct Node *next;
};

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    struct Node *head = NULL;
    struct Node *tail = NULL;
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            return 0;
        }
        struct Node *node = malloc(sizeof(struct Node));
        if (node == NULL) {
            return 1;
        }
        node->val = x;
        node->next = NULL;
        if (head == NULL) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
    }
    struct Node *prev = NULL;
    struct Node *cur = head;
    while (cur != NULL) {
        struct Node *nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    head = prev;
    for (struct Node *p = head; p != NULL; p = p->next) {
        if (p != head) {
            printf(" ");
        }
        printf("%d", p->val);
    }
    printf("\n");
    while (head != NULL) {
        struct Node *nxt = head->next;
        free(head);
        head = nxt;
    }
    return 0;
}
